function equipmentPlacement(gear){const rows={1:0,3:0};return gear.map((g,i)=>{const type=(g.type||'').toLowerCase(),slot=(g.slot||'').toLowerCase();let column=1,rank=10;if(/shield|ammo/.test(type+' '+slot)){column=3;rank=/ammo/.test(type+' '+slot)?101:100;}else if(/weapon|bow|torch|hand|sword|axe|spear|mace|polearm|staff|knife|crossbow/.test(type+' '+slot)){column=1;rank=100;}else if(/cape|shoulder/.test(type+' '+slot)){column=3;rank=1;}else if(/utility|accessory|ring|necklace/.test(type+' '+slot)){column=3;rank=2;}else rank=/head|helmet/.test(type+' '+slot)?1:/chest/.test(type+' '+slot)?2:/leg/.test(type+' '+slot)?3:10;return {g,i,column,rank};}).sort((a,b)=>a.rank-b.rank||a.i-b.i).map(item=>({...item,row:rows[item.column]=Math.max(rows[item.column]+1,item.rank>=100?5:1)}));}
