 document.body.classList.toggle('scenic-profile',full);document.body.classList.toggle('scrolling-profile',full&&backdropMode==='scroll');document.body.classList.toggle('grounded-profile',active);
 const layer=$('profileBackdrop');layer.hidden=!full;
