 let footX=width/2,footY=full?profileTop+(innerWidth<=720?480:590):box.height*.76;
 if(active&&img?.naturalWidth&&img.getBoundingClientRect().height&&!img.classList.contains('media-failed')){
  const r=img.getBoundingClientRect(),fit=Math.min(r.width/img.naturalWidth,r.height/img.naturalHeight),paintHeight=img.naturalHeight*fit;
  // Body crops have 2.5% transparent padding on each side. Account for object-fit letterboxing too.
  const x=r.left+r.width/2,y=r.top+(r.height-paintHeight)/2+paintHeight*(1-1/42);
  const sr=symbol.getBoundingClientRect();symbol.style.setProperty('--foot-top',(y-sr.top)+'px');symbol.style.setProperty('--foot-width',Math.min(180,img.naturalWidth*fit*.48)+'px');symbol.dataset.grounded='true';
  lastGround={player:state.profile,world:state.filter.world,width:innerWidth,x,y:y+scrollY};
  footX=full?x:x-box.left;footY=full?y+scrollY:y-box.top;
 }else if(full&&lastGround?.player===state.profile&&lastGround.world===state.filter.world&&lastGround.width===innerWidth){footX=lastGround.x;footY=lastGround.y;}
 else if(symbol)delete symbol.dataset.grounded;
