$('vikingDirectorySearch').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();$('vikingDirectorySearch').value='';renderVikingDirectory();}if(e.key==='ArrowDown'||e.key==='Enter'){e.preventDefault();$('vikingDirectoryResults').querySelector('button')?.focus();}});
function directoryProgress(p){const bosses=state.data?.bossCatalog||[],done=new Set(p.completedBossKeys||[]),count=bosses.filter(b=>done.has(b.key)).length;return '<span class="directory-progress"><span class="directory-progress-heading"><span>Recorded boss victories</span><b>'+count+' / '+bosses.length+'</b></span><span class="directory-bosses">'+bosses.map(b=>'<span class="directory-boss '+(done.has(b.key)?'complete':'')+'" title="'+esc(b.name)+' '+(done.has(b.key)?'1/1 recorded':'0/1 recorded')+'"><span>'+esc(b.name.replace(/^The /,'').split(' ')[0])+'</span><b>'+(done.has(b.key)?'1/1':'0/1')+'</b></span>').join('')+'</span></span>';}
function directorySaga(p){const latest=(state.data?.chapters||[]).filter(c=>c.playerId===p.playerId&&c.model!=='local-template').sort((a,b)=>Date.parse(b.utc)-Date.parse(a.utc))[0],text=(latest?.characterBio&&latest.characterBioModel!=='local-template'?latest.characterBio:sagaProse(latest?.text)).replace(/\s+/g,' ').trim();let excerpt=text.slice(0,220);if(text.length>220){const space=excerpt.lastIndexOf(' ');if(space>150)excerpt=excerpt.slice(0,space);excerpt+='\u2026';}return '<span class="directory-saga"><span class="directory-saga-label">'+(text?'From their saga <small>AI fiction</small>':'Their saga')+'</span><span class="directory-saga-excerpt'+(text?'':' is-empty')+'">'+esc(excerpt||'No saga has been written yet.')+'</span></span>';}
